  "dlgBiblioteka.kliknijElementZebyWstawic": "Kliknij element, żeby wstawić go na środek strony, albo przeciągnij go na stronę.",
  "dlgCzcionki.czcionki": "Czcionki",
  "dlgCzcionki.makietka": ".makietka",
  "dlgCzcionki.mojeCzcionkiZInnych": "Moje czcionki z innych projektów",
  "dlgCzcionki.oficjalnyZestawAplikacjiTen": "Oficjalny zestaw aplikacji – ten sam dla wszystkich projektów i wszystkich użytkowników. Te czcionki są na liście w każdym projekcie, trafiają do pliku PDF, a ich pliki można pobrać (np. dla drukarni albo grafika). Wszystkie na licencji SIL Open Font License – wolno ich używać w druku komercyjnym.",
  "dlgCzcionki.wlasneCzcionkiProjektu": "Własne czcionki projektu",
