  "dlgInstalacjaIos.naIphonieIIpadzie": "Na iPhonie i iPadzie aplikację dodaje się z menu Safari – potem otwiera się ją z ekranu początkowego, na całym ekranie.",
  "dlgInstalacjaIos.rozumiem": "Rozumiem",
