  "dlgInstrukcja.zamknijInstrukcje": "Zamknij instrukcję",
  "dlgKoloryDruku.drukKolorow": "Druk kolorów",
  "dlgKoloryDruku.farbaMieszanaOsobnoNp": "Farba mieszana osobno, np. Pantone – w PDF to osobna płyta. Wpisz nazwę tak, jak podaje drukarnia albo wzornik; CMYK obok służy tylko do podglądu na ekranie. Nowy kolor dodatkowy możesz też dodać od razu przy elemencie – w wyborze koloru albo we Właściwościach → „Wykończenie druku”.",
  "dlgKoloryDruku.gotowe": "Gotowe",
  "dlgKoloryDruku.koloryDodatkoweNpPantone": "Kolory dodatkowe (np. Pantone)",
  "dlgKoloryDruku.koloryUzyteWProjekcie": "Kolory użyte w projekcie i to, jak pójdą do druku. Ustawisz je dla całego projektu albo osobno dla jednej sekcji – np. okładka w pełnym kolorze, a środek czarno-biały.",
  "dlgKoloryDruku.lakierZlocenieTloczenieI": "Lakier, złocenie, tłoczenie i biel ustawiasz przy elemencie: zaznacz go i wybierz we Właściwościach → „Wykończenie druku”. Tu widać, co jest w projekcie.",
  "dlgKoloryDruku.rozszerzonyCmykIInne": "Rozszerzony CMYK i inne farby",
  "dlgKoloryDruku.rozszerzonyCmykNpCmyk": "Rozszerzony CMYK (np. CMYK + pomarańczowy, zielony i fioletowy) robi drukarnia sama z Twojego pliku – nie trzeba osobnej palety. Biel, lakier, złocenie i tłoczenie trafiają do PDF jako osobne płyty z nadrukiem (drukarnia widzi, gdzie je położyć).",
  "dlgKoloryDruku.wykonczeniaDruku": "Wykończenia druku",
