  "dlgKontrola.sprawdzPrzedDrukiem": "Sprawdź przed drukiem",
  "dlgKontrola.uwagiDoCalegoProjektu": "Uwagi do całego projektu, już po powieleniu serii: pola bez wartości, brakujące obrazy, powtórzenia, braki danych i teksty, które nie mieszczą się w ramkach.",
  "dlgListaKolumny.anuluj": "Anuluj",
  "dlgListaKolumny.komorkiZInnaWartoscia": "Komórki z inną wartością są podświetlone i trafiają na listę „Sprawdź przed drukiem”. W szablonie danych komórki tej kolumny dostaną listę rozwijaną.",
