  "kontrola.poleNieMaSkad": "Pole {nazwa} nie ma skąd wziąć wartości (nie ma takiej kolumny ani pola dokumentu) – {size|strona|strony|strony} {lista}.",
  "kontrola.przezroczyste": "przezroczyste",
  "kontrola.saLinieZgieciaAlbo": "Są linie zgięcia albo miejsca klejenia, a nie ma linii cięcia – składanka nie da się wyciąć. Oznacz obrys kawałka jako „Cięcie” (Kolory do druku → Wykończenie). {size|Strona|Strony|Strony} {lista}.",
  "kontrola.sekcjaJestNaBiale": "Sekcja „{nazwa}” jest na {podloze}: białe elementy nie wydrukują się (biel to brak farby) – wyjdą {x}. Ustaw im biały poddruk (Kolory do druku → Uszlachetnienie) albo inny kolor. {size|Strona|Strony|Strony} {lista}.",
  "kontrola.sekcjaJestNaPrzezroczystej": "Sekcja „{nazwa}” jest na przezroczystej folii, a żaden element nie ma białego poddruku – kolory będą prześwitywać. Jeśli mają być kryjące, ustaw pod nimi biały poddruk.",
  "kontrola.sekcjaMaDoPelnej": "Sekcja „{nazwa}” ma {stron} {stron|stronę|strony|stron} – do pełnej składki po {skladka} brakuje {brakuje}. Dodaj strony albo użyj „Dopełnij pustymi” na liście stron.",
  "kontrola.seriaOdStronyStrony": "Seria „{nazwa}”: od strony {zamianaOd} strony bloku wychodzą po przeciwnej stronie rozkładówki niż w układzie stron (lewa po prawej, prawa po lewej). Zaznacz w oknie serii „Pilnuj lewej i prawej strony”, a w takim miejscu stanie pusta strona.",
  "kontrola.seriaPowielaSieRazy": "Seria „{nazwa}” powiela się {ile} razy, a tabela ma {zDanymi} {zDanymi|wiersz|wiersze|wierszy}{x} – wartości zaczną się powtarzać.",
  "kontrola.seriaTabelaMaA": "Seria „{nazwa}”: tabela „{nazwa2}” ma {jest} {jest|wiersz|wiersze|wierszy}, a potrzeba {potrzeba} ({opisKroku}). Od strony {brakOd}{x} jej pola zostaną puste.",
  "kontrola.seriaTabelaMaA2": "Seria „{nazwa}”: tabela ma {wierszy} {wierszy|wiersz|wiersze|wierszy}, a blok {dlugosc} {dlugosc|stronę|strony|stron} – ostatnie powielenie jest dokończone stronami bez danych.",
  "kontrola.seriaWszystkieWierszeTabeli": "Seria „{nazwa}”: wszystkie wiersze tabeli są pomijane ({ZNACZNIK_POMIJANIA}) – seria nie daje żadnej strony.",
  "kontrola.seriaZebyStronyLewe": "Seria „{nazwa}”: {ile|wstawiona została pusta strona|wstawione zostały puste strony|wstawionych zostało pustych stron} ({ile|strona|strony|strony} {lista}), żeby strony lewe zostały po lewej, a prawe po prawej. Pusta strona jest biała i liczy się w numeracji.",
  "kontrola.tekst": "{opis} {size|Strona|Strony|Strony} {join}.",
  "kontrola.tekst2": " {stronyIle|Strona|Strony|Strony} {join}.",
  "kontrola.wKolorzePapieru": "w kolorze papieru",
  "kontrola.wartoscWKolumnieTabela": "Wartość „{wartosc}” w kolumnie „{kolumna}” (tabela „{nazwa}”) powtarza się w wierszach {lista}.",
  "kontrola.wartoscWKolumnieTabela2": "Wartość „{wartosc}” w kolumnie „{kolumna}” (tabela „{nazwa}”) nie jest na liście dozwolonych wartości – {wierszeIle|wiersz|wiersze|wiersze} {lista}.",
  "kontrola.wartoscZKolumnyTabela": "Wartość „{wartosc}” z kolumny „{kolumna}” (tabela „{nazwa}”) powtarza się na stronach {lista}.",
