  "kontrolaElementow.bezSpadu": "Element „{nazwa}” dochodzi do krawędzi strony, ale nie do spadu ({spad} mm) – po przycięciu może zostać biały pasek; przeciągnij go za krawędź – {gdzie}.",
  "kontrolaElementow.brakCzcionki": "Tekst „{nazwa}” używa czcionki {czcionki}, której nie ma w projekcie ani w Makietce – w PDF zastąpi ją inna; wgraj ją w Czcionkach projektu – {gdzie}.",
