  "kontrolaElementow.pozaStrona": "Element „{nazwa}” leży całkiem poza stroną – nie będzie go w druku – {gdzie}.",
  "kontrolaElementow.przyKrawedzi": "Tekst „{nazwa}” jest bliżej niż {mm} mm od krawędzi cięcia – przy przycinaniu może zostać ucięty – {gdzie}.",
