  "skladankaSzablony.doPudelkaOPodanych": "Do pudełka o podanych wymiarach: dwie płytki ze szczelinami do połowy – wsuwasz jedną w drugą i wkładasz do środka.",
  "skladankaSzablony.dwieCzesciPudelkoI": "Dwie części: pudełko i wieczko większe o dwie grubości materiału i luz – nakłada się ciasno, ale bez wciskania.",
  "skladankaSzablony.dwieScianyZLukami": "Dwie ściany z łukami na końcach – zgięcia po łuku domykają pudełko bez kleju na końcach.",
