  "skladankaSzablony.jedenArkuszNacieciaI": "Jeden arkusz: nacięcia i zgięcia – po otwarciu kartki pod kątem prostym pudełka wyskakują ze środka. Nic nie wystaje po zamknięciu (nacięcia kończą się przed brzegiem).",
  "skladankaSzablony.jednaCzescPasCzterech": "Jedna część: pas czterech ścian, wieko i dno, zakładki klejowe.",
  "skladankaSzablony.kartkaIPasekPrzyklejony": "Kartka i pasek przyklejony zakładkami po obu stronach grzbietu – po otwarciu stoi jak pudełko, po zamknięciu leży płasko w środku.",
  "skladankaSzablony.klinyOdBiegunaDo": "Kliny od bieguna do bieguna (4–24) – każdy przykleja się zakładkami do następnego; im więcej klinów, tym okrąglej.",
  "skladankaSzablony.kulaKlinN": "Kula – klin {n}",
  "skladankaSzablony.mechanizmWiekoNaZawiasie": "Mechanizm: wieko na zawiasie z językiem wsuwanym za przednią ścianę – otwiera się i zamyka bez kleju.",
  "skladankaSzablony.mechanizmWiekoZJezykiem": "Mechanizm: wieko z językiem wsuwanym w szczelinę w przedniej ścianie – zamyka się na zatrzask (szczelina na grubość materiału).",
  "skladankaSzablony.mniejszaPlatformaWKacie": "Mniejsza platforma w kącie między pierwszą a kartką: {d2} mm przy platformie, {d1} mm przy kartce.",
  "skladankaSzablony.nacieciaCzerwonePrzetnijZegnij": "Nacięcia (czerwone) przetnij, zegnij według linii i otwórz kartkę pod kątem prostym – {x} na {r2} mm.",
  "skladankaSzablony.nadwozieZMaskaKabina": "Nadwozie z maską, kabiną i bagażnikiem – bryła z sylwetki rozłożona automatycznie (koła dorysuj albo doklej osobno).",
  "skladankaSzablony.narysujTuToCo": "Narysuj tu to, co zasłaniają klapki, i przyklej kartkę na wierzch – klej tylko poza okienkami.",
  "skladankaSzablony.okienkaWycieteZTrzech": "Okienka wycięte z trzech stron i zgięte na czwartej (zawias) – pod nimi druga kartka z ukrytym obrazkiem.",
