  "skladankaSzablony.pasScianIDwie": "Pas ścian i dwie podstawy przy pierwszej ścianie.",
  "skladankaSzablony.plaszczWycinekKolaZ": "Płaszcz – wycinek koła – z zakładkami do dna; kąt rozwinięcia liczony z wysokości i średnicy.",
