  "tresc.kontrola.kolorZapisD1495bAlboNazwe": "Kolor: zapis #d1495b albo nazwę po angielsku, np. navy. Pusta komórka zostawia kolor wzoru.",
  "tresc.kontrola.ktoraCzescZdjeciaPokazacGora": "Którą część zdjęcia pokazać: góra, dół, lewa, prawa, środek – albo punkt zdjęcia w procentach od lewej i od góry, np. 30% 20%. Pusta komórka zostawia ustawienie wzoru.",
