  "tresc.makietaOkno.alboOtworzMakietkeWB": "Albo otwórz Makietkę w <b>Safari</b> – na starszych Macach zwykle pokazuje makietę bez zmian w ustawieniach.",
  "tresc.makietaOkno.nieznanyBladGrafiki": "nieznany błąd grafiki",
  "tresc.makietaOkno.poprzednioMakietaZamknelaSieNieoczekiwanie": "Poprzednio makieta zamknęła się nieoczekiwanie (zwykle brakuje pamięci w telefonie) – teraz działa w trybie oszczędnym: mniej stron naraz i mniejsza rozdzielczość stron.",
  "tresc.makietaOkno.sprawdzWChromeUstawienieB": "Sprawdź w Chrome ustawienie <b>Ustawienia → System → Używaj akceleracji grafiki, gdy jest dostępna</b> – ma być włączone (potem uruchom Chrome ponownie).",
  "tresc.makietaOkno.toUrzadzenieNiePokazujeGrafiki": "To urządzenie nie pokazuje grafiki 3D – makieta jest narysowana w wersji uproszczonej (bez cieni rzucanych i połysku). Obracanie i kartkowanie działają tak samo.",
  "tresc.makietaOkno.wpiszWPaskuAdresuB": "Wpisz w pasku adresu <b>chrome://gpu</b>. Jeśli przy „WebGL” jest „Unavailable” albo „Software only”, Chrome zablokował kartę graficzną tego komputera (częste na starszych komputerach). Wtedy otwórz <b>chrome://flags/#ignore-gpu-blocklist</b>, ustaw „Override software rendering list” na <b>Enabled</b> i uruchom Chrome ponownie.",
  "tresc.makietaOkno.zaktualizujPrzegladarkeISystemPrzy": "Zaktualizuj przeglądarkę i system; przy oszczędzaniu baterii grafika bywa wyłączona – wyłącz je na chwilę.",
  "tresc.makietaOpis.broszuraZeszytowaArkuszeZlozoneNa": "Broszura zeszytowa – arkusze złożone na pół i zszyte w zgięciu (liczba stron podzielna przez 4).",
  "tresc.makietaOpis.kalendarzSciennyMaZwykle13": "Kalendarz ścienny ma zwykle 13 kart (okładka i 12 miesięcy) – projekt ich nie ma. Brakujące karty będą białe; zacznij od szablonu „Kalendarz ścienny z plecami”.",
  "tresc.makietaOpis.miekka": "miękką",
  "tresc.makietaOpis.miekkaKlejona": "miękką klejoną",
  "tresc.makietaOpis.notesNaSpiraliStronyProjektu": "Notes na spirali – strony projektu zepnie spirala; okładka (jeśli jest) będzie pierwszą kartą.",
  "tresc.makietaOpis.projektNieMaOkladkiMakieta": "Projekt nie ma okładki – makieta pokaże pustą, ciemną okleinę. Dodaj sekcję typu „Okładka” z twardą oprawą albo zacznij od szablonu projektu „Książka w twardej oprawie”.",
  "tresc.makietaOpis.twarda": "twardą",
  "tresc.makietaOpis.zeszytowa": "zeszytową",
  "tresc.markaOkno.koloryCzcionkiStyleILogo": "Kolory, czcionki, style i logo tego zestawu znikną z konta. Projekty, które go używały, przejdą na zestaw w użyciu; to, co już jest na ich stronach, zostaje.",
