  "tresc.oknoDruku.broszuraDrukujBDwustronnieObracanie": "Broszura: drukuj <b>dwustronnie, obracanie po krótszej krawędzi</b> (kartka leży poziomo). Na odwrocie kartki 1 są strony 2 i 7.",
  "tresc.oknoDruku.drukarkaBezDrukuDwustronnegoWydrukuj": "Drukarka bez druku dwustronnego: wydrukuj najpierw <b>tylko strony nieparzyste</b>, włóż stos z powrotem (zadrukowaną stroną zgodnie z instrukcją drukarki), potem <b>parzyste</b>.",
  "tresc.oknoDruku.dwustronnieKartkaZKilkomaStronami": "Dwustronnie: kartka z kilkoma stronami leży poziomo – obracanie po <b>krótszej</b> krawędzi.",
  "tresc.oknoDruku.dwustronnieObracaniePoBDluzszej": "Dwustronnie: obracanie po <b>dłuższej</b> krawędzi (kartka pionowo).",
  "tresc.oknoDruku.jesliWybralesZnakiCieciaPo": "Jeśli wybrałeś znaki cięcia, po zszyciu przytnij brzegi wzdłuż znaków (nożykiem przy linijce albo w punkcie ksero).",
  "tresc.oknoDruku.najpierwWydrukujBJednaKartke": "Najpierw wydrukuj <b>jedną kartkę na próbę</b> (w oknie drukarki: strony 1–2) i sprawdź, czy strony stoją dobrze.",
  "tresc.oknoDruku.wRzeczywistymRozmiarzeZmniejszoneTylko": "w rzeczywistym rozmiarze (zmniejszone tylko, gdy się nie mieszczą)",
  "tresc.oknoDruku.zlozKartkiRazemNaPol": "Złóż kartki razem na pół (pierwsza kartka na wierzchu), wyrównaj i <b>zszyj w zgięciu</b> (2 zszywki). Grubą broszurę podziel na składki po kilka kartek.",
  "tresc.oknoPdf.obrazyStronSaPrzeliczoneNa": "Obrazy stron są przeliczone na CMYK przez ten profil. Czarny i szary tekst, kształty i cienie idą samą czarną farbą (także gdy leżą na zdjęciu) i są zapisane bez strat, więc litery są ostre; same zdjęcia – czterema farbami, jak wynika z profilu, jako JPEG. Plik jest większy niż zwykłe obrazy stron.",
  "tresc.oknoPdf.zdjeciaSaPrzeliczoneNaCmyk": "Zdjęcia są przeliczone na CMYK przez ten profil, w rozdzielczości z pola „Jakość” (zdjęcia JPEG zostają JPEG-iem w czterech farbach, pozostałe obrazy bez strat) – plik będzie większy.",
  "tresc.oknoPdf.zdjeciaZostajaWRgbZ": "Zdjęcia zostają w RGB z opisem sRGB – na farby przeliczy je drukarnia według dołączonego profilu (to zgodne z PDF/X-4).",
  "tresc.panelStrony.bezWzorcow": "bez wzorców",
