  "tresc.powiadomienia.naIphonieIIpadziePowiadomienia": "Na iPhonie i iPadzie powiadomienia działają w zainstalowanej aplikacji. Zainstaluj Makietkę, otwórz ją z ekranu początkowego i włącz je tutaj.",
  "tresc.profilIcc.profilNieMaTablicPrzeliczeniowych": "profil nie ma tablic przeliczeniowych CMYK",
