  "tresc.pubCzytnik.tenPlikPublisheraJestW": "Ten plik Publishera jest w starszym formacie (Publisher 98/2000) albo uszkodzony – otwórz go w nowszym Publisherze, zapisz i spróbuj jeszcze raz.",
