  "tresc.raportPrzeniesienia.polaczoneRamkiTekstuRozdzieloneKazda": "połączone ramki tekstu rozdzielone – każda ma swój kawałek tekstu, tekst się nie przelewa",
  "tresc.raportPrzeniesienia.przypisyDolneZostajaJakoNumery": "przypisy dolne (zostają jako numery w tekście)",
  "tresc.raportPrzeniesienia.serieRozwinieteWGotoweStrony": "serie rozwinięte w gotowe strony z wpisanymi danymi (pola nie przechodzą – do korespondencji seryjnej w programie: „Seria dla innego programu”)",
  "tresc.raportPrzeniesienia.styleTekstuZapisaneJakoZwykle": "style tekstu zapisane jako zwykłe formatowanie (bez nazwanych stylów)",
