  "tresc.skladanka.docisnijSklejoneMiejscaIOdczekaj": "Dociśnij sklejone miejsca i odczekaj, aż klej wyschnie.",
  "tresc.skladanka.odpadWyciecie": "Odpad (wycięcie)",
  "tresc.skladanka.sciana": "Ściana",
  "tresc.skladanka.zegnijWszystkieLiniePrzedKlejeniem": "Zegnij wszystkie linie przed klejeniem – przyłóż linijkę i przeciągnij tępą stroną noża. Kreska–kropka („góra”) – zginaj od siebie, nadruk zostaje na zewnątrz; same kreski („dolina”) – do siebie. Zakładki zaginaj pod spód.",
  "tresc.skladankaNarzedzia.bryla": "Bryła",
  "tresc.skladankaNarzedzia.liniaKlejeniaKliknijPoczatekI": "Linia klejenia: kliknij początek i koniec w dowolnym miejscu części – nie musi dochodzić do krawędzi (Esc kończy). Krzywą albo łamaną narysuj linią lub piórem na części, zaznacz i użyj [Linia klejenia].",
  "tresc.skladankaNarzedzia.liniaKlejeniaWDowolnymMiejscu": "Linia klejenia – w dowolnym miejscu ściany",
  "tresc.skladankaNarzedzia.miejsceKlejeniaKliknijWCzesci": "Miejsce klejenia: kliknij w części (z Shiftem – na spodzie, bez druku). Esc kończy.",
  "tresc.skladankaNarzedzia.naciecieKliknijPoczatekIKoniec": "Nacięcie: kliknij początek i koniec – w środku części albo od jej krawędzi, pod dowolnym kątem (Esc kończy). Krzywe albo łamane: narysuj linię lub pióro na części, zaznacz i użyj [Nacięcie].",
  "tresc.skladankaNarzedzia.naciecieLiniaCieciaWSrodku": "Nacięcie – linia cięcia w środku części, pod dowolnym kątem",
  "tresc.skladankaNarzedzia.polaczKliknijPrzyKrawedziKtora": "Połącz: kliknij przy krawędzi, która dostanie zakładkę, potem przy krawędzi, do której się przykleja – albo w środku ściany (miejsce klejenia). Esc kończy.",
  "tresc.skladankaNarzedzia.polaczKrawedzZKrawedziaAlbo": "Połącz – krawędź z krawędzią albo z miejscem",
  "tresc.skladankaNarzedzia.rozetnijKliknijPunktNaKrawedzi": "Rozetnij: kliknij punkt na krawędzi części, potem drugi – część podzieli się na dwie z zakładką na linii cięcia (Esc kończy).",
  "tresc.skladankaNarzedzia.scalKliknijPrzyKrawedziZ": "Scal: kliknij przy krawędzi z numerem pary – druga część dołączy się w tym miejscu, a krawędź stanie się zgięciem (Esc kończy).",
  "tresc.skladankaNarzedzia.szczelinaKliknijPoczatekIKoniec": "Szczelina: kliknij początek i koniec nacięcia w części – szerokość z grubości materiału (Esc kończy).",
  "tresc.skladankaNarzedzia.szczelinaNaWypustkeZSzerokoscia": "Szczelina – na wypustkę (z szerokością)",
  "tresc.skladankaNarzedzia.wPlikuNieMaScian": "W pliku nie ma ścian – czy to na pewno model OBJ albo STL?",
  "tresc.skladankaNarzedzia.wyjmijZCzesciDoEdycji": "Wyjmij z części (do edycji)",
  "tresc.skladankaNarzedzia.zeSkosnaLiniaPoDrugiej": " – ze skośną linią po drugiej stronie grzbietu doklejona część stanie pod kątem jak zgięcie V",
  "tresc.skladankaNarzedzia.zgiecieDwaKliknieciaNaKrawedziach": "Zgięcie – dwa kliknięcia na krawędziach",
  "tresc.skladankaNarzedzia.zgiecieKliknijPunktNaKrawedzi": "Zgięcie: kliknij punkt na krawędzi części, potem drugi punkt na krawędzi – linia podzieli część na ściany (Esc kończy).",
