  "wlasciwosci.naKazdejPowielonejStronie": "Na każdej powielonej stronie pojawi się obraz o nazwie wpisanej w tej kolumnie (np. zdjecie-01.jpg), wpisany w ramkę tego obrazu. Pliki wgraj w oknie „Obrazy projektu” (przycisk u góry panelu) – tam też skopiujesz ich nazwy do tabeli.",
  "wlasciwosci.naKazdejStronieSerii": "Na każdej stronie serii kalendarz pokazuje miesiąc z tej kolumny – np. „2027-03”, „marzec 2027” albo „3”. W edytorze widać miesiąc z pierwszego wiersza.",
